ewlabel{app:beta03}{{E.1}{18}{Per-Seed Results at $ eta {=}0.2$ and $ eta {=}0.3$}{subsection.E.1}{}}

ewlabel{app:llama-coldstart}{{E.4}{19}{Cross-Model Generalization: LLaMA-3.2-3B Cold-Start Failure}{subsection.E.4}{}}

ewlabel{app:seed-convergence}{{E.5}{20}{Seed-Dependent Convergence in Exec-Only GRPO}{subsection.E.5}{}}

ewlabel{app:8b-results}{{E.6}{20}{Cross-Scale: Qwen3-8B Exec-Only GRPO}{subsection.E.6}{}}

ewlabel{tab:fol-detailed}{{7}{22}{Detailed per-seed results: FOL (Prover9). Includes the per-seed $ eta {=}0.1$ breakdown referenced from Table~ef {tab:goodhart-landscape}. PR = prove rate, ISR$^*$ = proved-only ISR, TS/CE/N-H\ = percentage among proved samples. ``---'' indicates data not available. $^\dagger $s43 uses sampling eval ($T{=}0.7$). $^\ddagger $Three s44-1000 samples escape text-match heuristics (CE/PG classifiers) but exhibit ISR${=}0$ and functionally degenerate proof structures: disjunctive conclusions that bypass PG detection and commuted premises that bypass CE detection; reclassified as degenerate. $^\diamond $Seeds 45--46 added post-hoc under identical hyperparameters (effective batch size 8; micro-batch decomposition differs: $4{	imes }2$ vs.\ $2{	imes }4$, mathematically equivalent)}{table.caption.77}{}}

ewlabel{tab:fol-beta01-detailed}{{7}{22}{Detailed per-seed results: FOL (Prover9). Includes the per-seed $ eta {=}0.1$ breakdown referenced from Table~ef {tab:goodhart-landscape}. PR = prove rate, ISR$^*$ = proved-only ISR, TS/CE/N-H\ = percentage among proved samples. ``---'' indicates data not available. $^\dagger $s43 uses sampling eval ($T{=}0.7$). $^\ddagger $Three s44-1000 samples escape text-match heuristics (CE/PG classifiers) but exhibit ISR${=}0$ and functionally degenerate proof structures: disjunctive conclusions that bypass PG detection and commuted premises that bypass CE detection; reclassified as degenerate. $^\diamond $Seeds 45--46 added post-hoc under identical hyperparameters (effective batch size 8; micro-batch decomposition differs: $4{	imes }2$ vs.\ $2{	imes }4$, mathematically equivalent)}{table.caption.77}{}}

ewlabel{tab:prolog-detailed}{{8}{23}{Detailed per-seed results: Prolog (SWI-Prolog 8.4.2). PR = prove rate, ISR$^*$ = proved-only ISR, TS/CE/N-H\ = percentage among proved samples. ``---'' indicates data not available}{table.caption.78}{}}

ewlabel{tab:prooffol-detailed}{{9}{23}{Detailed per-seed results: ProofFOL (Prover9). PR$_{	ext {f50}}$ = mean prove rate over final 50 steps. TS = tautological shortcutting (\S ef {sec:taxonomy}), CE = conclusion embedding, Genuine = classified as neither TS nor CE. Stable convergence: PR$_{	ext {f50}}{>}0.90$}{table.caption.79}{}}

ewlabel{tab:beta03-detailed}{{10}{23}{Per-seed results at $ eta {=}0.2$ and $ eta {=}0.3$ (FOL). PR = prove rate, ISR$^*$ = proved-only ISR, TS/CE/N-H = percentage among proved samples}{table.caption.82}{}}

ewlabel{tab:8b-config}{{11}{24}{Configuration differences between 4B and 8B GRPO runs. $K{=}8$ is required at 8B scale because $K{=}4$ produces near-identical rollouts, eliminating gradient signal}{table.caption.86}{}}

ewlabel{tab:8b-comparison}{{12}{24}{Cross-scale comparison. The 4B model converges with structural degeneration; both 8B configurations fail to converge, preserving structural integrity. $K{=}8$ provides partial gradient signal absent in $K{=}4$ but insufficient for convergence within 500 steps}{table.caption.87}{}}

