python3 -c "
import fitz
doc = fitz.open('main.pdf')
print(f'Total pages: {len(doc)}')
for i, page in enumerate(doc):
    text = page.get_text()
    if '\\nReferences\\n' in text or text.strip().startswith('References'):
        print(f'References starts on page {i+1}')
    if 'Limitations' in text and i > 3:
        first_line = [l for l in text.split('\\n') if 'Limitations' in l]
        if first_line:
            print(f'Limitations on page {i+1}')
    if i > 5:
        for kw in ['Appendix', 'A ', 'B ', 'C ', 'D ', 'E ']:
            pass
doc.close()
" 2>/dev/null || echo "PyMuPDF not available"
